```python
class Solution:
    def findMedianSortedArrays(self, nums1, nums2):
        a, b = nums1, nums2
        if len(a) > len(b):
            a, b = b, a
        m, n = len(a), len(b)
        left, right = 0, m
        half = (m+n+1)//2
        while left <= right:
            i = (left+right)//2
            j = half-i
            al = a[i-1] if i else float('-inf')
            ar = a[i] if i < m else float('inf')
            bl = b[j-1] if j else float('-inf')
            br = b[j] if j < n else float('inf')
            if al > br:
                right = i-1
            elif bl > ar:
                left = i+1
            elif (m+n) % 2:
                return max(al, bl)
            else:
                return (max(al, bl)+min(ar, br))/2
```

