class Solution:
    def canPartition(self, nums):
        total = sum(nums)
        if total % 2:
            return False
        target = total//2
        bits = 1
        mask = (1 << (target+1))-1
        for value in nums:
            bits = (bits | (bits << value)) & mask
        return bool(bits & (1 << target))
